		m_cpu->set_state_int(tms320c54x_device::STATE_ST1, 0x800);
		m_cpu->set_state_int(tms320c54x_device::STATE_PRD, family == 0 ? 0x1234 : family == 1 ? 0xaaaa : 0xffff);
