		m_cpu->set_state_int(tms320c54x_device::STATE_ST0, 0xa608);
		m_cpu->set_state_int(tms320c54x_device::STATE_ST1, 0x800);
		m_cpu->set_state_int(tms320c54x_device::STATE_A, b ? 0x9999 : nonzero ? 0x0100000000ULL : 0);
