		m_cpu->set_state_int(tms320c54x_device::STATE_AR2, 0x420);
		m_cpu->set_state_int(tms320c54x_device::STATE_IFR, 0);
		m_cpu->set_state_int(tms320c54x_device::STATE_IMR, 0);
