		m_pipeline_write_tap = data.install_write_tap(0, 0xffff, "repeat_writa_no_data_write",
			[this](offs_t, u16 &, u16) { if (!machine().side_effects_disabled()) expect(false, "WRITA writes program memory, never data memory"); });
