		program.write_word(f.page + 0x9002, std::array<u16, 4>{0x0000, 0x0800, 0x0200, 0x0a00}[f.operation] | (f.destination << 8) | std::array<u16, 3>{0xf8, 0xe3, 0xeb}[f.form]);
