		m_cpu->set_state_int(tms320c54x_device::STATE_A, (f.kind & 1) ? 0xdead : consumer ? f.value : 0x11112222);
		m_cpu->set_state_int(tms320c54x_device::STATE_B, (f.kind & 1) ? consumer ? f.value : 0x11112222 : 0xdead);
