		for (int i = 0; i < f.shift; ++i) bits = (bits * 2) & 0xffffffffffULL;
		for (int i = 0; i < -f.shift; ++i) bits = (bits >> 1) | ((f.flags & 2) && (bits & 0x8000000000ULL) ? 0x8000000000ULL : 0);
		u32 stored = u32(bits);
