		unsigned first_write() const { return long_form ? 8 : 7; }
		u16 first_source() const { return kind >= 2 ? 11 : kind == 0 ? 0x900 + count : 0x900; }
		u16 source(unsigned i) const { return kind == 1 || kind == 3 ? first_source() + i : first_source() - i; }
