		program.write_word(0x602, mvkd ? 0x7000 | (form == 1 ? 0x90 : 0x80) | reg : 0x7210 | reg); program.write_word(0x603, source);
		program.write_word(0x604, 0xe922); program.write_word(0x700, 0xe911);
