		m_cpu->set_state_int(tms320c54x_device::STATE_IMR, 0);
		m_cpu->set_state_int(tms320c54x_device::STATE_TCR, 0x10);
		m_cpu->set_state_int(tms320c54x_device::STATE_SP, 0x1200);
