			handler.insert(handler.begin() + 5, {0x4807, 0xf030, 0x2000, 0xf040, 0x4900, 0x8807, 0xf495, 0xf495});
			handler[16] = 0x912;
			// This synthetic caller owns A=1; restore it before saved status.
