		for (unsigned i = 0; i < 128; ++i) { data.write_word(0x5000 + i, 0x1357 ^ (i * 0x2345)); data.write_word(0x6000 + i, 0xdead); data.write_word(0x7000 + i, 0xdead); data.write_word(0x7100 + i, 0xdead); }
