		m_cpu->set_state_int(tms320c54x_device::STATE_PMST, 0); m_cpu->set_state_int(tms320c54x_device::STATE_ST0, 0x260e);
		if (!f.family) m_cpu->set_state_int(tms320c54x_device::STATE_PMST, (variant % 64) & 32 ? 1 : 0);
