			program.write_word(0x05e1, 0x0123);
			program.write_word(0x05e2, 0x4f81); // DST B, *AR1
			program.write_word(0x05e3, 0x74d6);
			program.write_word(0x05e4, 0x0123);
			program.write_word(0x05e5, 0xf5e1); // IDLE
