				m_cpu->set_state_int(tms320c54x_device::STATE_PC, 0x05e0);
				m_cpu->set_state_int(tms320c54x_device::STATE_IDLE, 0);
				++m_phase;
				m_check_timer->adjust(attotime::from_usec(100));
				return;
