			program.write_word(0x05e8, 0x7681); // ST #lk,*AR1
			program.write_word(0x05e9, 0x5a5a);
			program.write_word(0x05ea, 0x75d6);
			program.write_word(0x05eb, 0x0124);
			program.write_word(0x05ec, 0xf5e1);
