			program.write_word(0x05e7, 0x0124);
			program.write_word(0x05e8, 0xf5e1);
			program.write_word(0x05ec, 0x75d6);
			program.write_word(0x05ed, 0x0124);
			program.write_word(0x05ee, 0xf5e1);
